const B=8;
function cells(n){return n*n;}
function placements(n,len){
 const out=[];
 for(let r=0;r<n;r++)for(let c=0;c<n;c++){
  if(c+len<=n){let m=0n;for(let k=0;k<len;k++)m|=1n<<BigInt(r*n+c+k);out.push(m);}
  if(len>1&&r+len<=n){let m=0n;for(let k=0;k<len;k++)m|=1n<<BigInt((r+k)*n+c);out.push(m);}
 }
 return out;
}
function halo(m,n){
 let h=0n;
 for(let i=0;i<n*n;i++){ if((m>>BigInt(i))&1n){ const r=(i/n)|0,c=i%n;
   for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){const rr=r+dr,cc=c+dc; if(rr>=0&&rr<n&&cc>=0&&cc<n)h|=1n<<BigInt(rr*n+cc);}}}
 return h;
}
function count(n,fleet){
 const P=fleet.map(l=>placements(n,l).map(m=>({m,h:halo(m,n)})));
 let total=0; const occSet=new Set();
 const rec=(i,occ,blocked,startIdx)=>{
  if(i===P.length){total++;occSet.add(occ.toString(36));return;}
  const list=P[i];
  // identical consecutive lengths -> enforce order to avoid double count
  const sameAsPrev = i>0 && fleet[i]===fleet[i-1];
  const from = sameAsPrev?startIdx:0;
  for(let j=from;j<list.length;j++){
   const p=list[j];
   if((p.m & blocked)!==0n) continue;
   rec(i+1, occ|p.m, blocked|p.h, j+1);
  }
 };
 rec(0,0n,0n,0);
 return {total,distinct:occSet.size};
}
const t0=Date.now();
console.log("8x8 (4,3,2):", JSON.stringify(count(8,[4,3,2])), (Date.now()-t0)+"ms");
